import numpy as np, random, ot
from scipy.optimize import linear_sum_assignment as lsa

def greedy(M):
    n=M.shape[0]
    assigned_j=[False]*n
    row_assign=[-1]*n
    for i in range(n):
        j=np.argmin(M[i])
        if not assigned_j[j]:
            row_assign[i]=j; assigned_j[j]=True
        else:
            # pick next smallest not assigned
            order=np.argsort(M[i])
            for j2 in order:
                if not assigned_j[j2]:
                    row_assign[i]=j2; assigned_j[j2]=True; break
    row,row2=[],[]
    for i,j in enumerate(row_assign):
        row.append(i); row2.append(j)
    return row,row2

for n in [100,200]:
    good=0
    trials=200
    for t in range(trials):
        np.random.seed(t)
        M=ot.dist(np.random.rand(n,2), np.random.rand(n,2))
        r1,c1=lsa(M)
        r2,c2=greedy(M)
        G1=np.zeros((n,n)); G1[r1,c1]=1
        G2=np.zeros((n,n)); G2[r2,c2]=1
        if np.allclose(G1,G2):
            good+=1
    print(n, good, 'of', trials)
